function ENT:Draw()self:DrawModel();local lp=LocalPlayer();if not IsValid(lp)or lp:GetPos():DistToSqr(self:GetPos())>650*650 then return end;local online=false;for _,row in ipairs(GRM.Electronics and GRM.Electronics.Topology and GRM.Electronics.Topology.devices or{})do if row.id==self:GetDeviceID()then online=row.online==true break end end;local p=self:GetPos()+Vector(0,0,self:OBBMaxs().z+12);local a=Angle(0,EyeAngles().y-90,90);cam.Start3D2D(p,a,.07);draw.RoundedBox(8,-155,-34,310,68,Color(9,14,23,235));draw.SimpleText(self:GetDisplayName(),"GRMNet_World",0,-10,Color(240,245,252),TEXT_ALIGN_CENTER,TEXT_ALIGN_CENTER);draw.SimpleText((online and"● ONLINE"or"○ OFFLINE").."  ·  "..self:GetNetworkID(),"GRMNet_WorldS",0,16,online and Color(70,215,130)or Color(230,100,90),TEXT_ALIGN_CENTER,TEXT_ALIGN_CENTER);cam.End3D2D()end
